package main
import (
 "context"
 "encoding/json"
 "fmt"
 "net/http"
 "net/http/httptest"
 "os"
 "runtime"
 "strings"
 "sync/atomic"
 "time"
 starmap "github.com/agentstation/starmap"
 "github.com/agentstation/starmap/pkg/catalogs/storage"
 s3store "github.com/agentstation/starmap/pkg/catalogs/storage/s3"
 "github.com/aws/aws-sdk-go-v2/aws"
 awss3 "github.com/aws/aws-sdk-go-v2/service/s3"
)
func stacks() map[string]string {
 buffer := make([]byte, 1<<20)
 used := runtime.Stack(buffer, true)
 if used == len(buffer) { panic("stack buffer full") }
 result := map[string]string{}
 for _, stack := range strings.Split(strings.TrimSpace(string(buffer[:used])), "\n\n") {
  result[strings.Fields(stack)[1]] = stack
 }
 return result
}
func main() {
 var requests atomic.Int64
 server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
  requests.Add(1)
  w.Header().Set("Content-Type", "application/xml")
  w.WriteHeader(http.StatusNotFound)
  fmt.Fprint(w, "<Error><Code>NoSuchKey</Code></Error>")
 }))
 defer server.Close()
 backend, err := s3store.New(awss3.New(awss3.Options{
  Region: "us-east-1", BaseEndpoint: aws.String(server.URL), UsePathStyle: true,
  Credentials: aws.AnonymousCredentials{}, RetryMaxAttempts: 1,
 }), s3store.Config{Bucket: "local-probe"})
 if err != nil { panic(err) }
 store, err := storage.NewObject(backend, "catalog")
 if err != nil { panic(err) }
 ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
 defer cancel()
 before := stacks()
 client, err := starmap.NewContext(ctx, starmap.WithCatalogStore(store))
 result := map[string]any{"network_requests": requests.Load(), "constructor_error": "", "catalog_available": client != nil && client.Catalog() != nil}
 extra := []string{}
 for id, stack := range stacks() { if _, found := before[id]; !found { extra = append(extra, stack) } }
 result["new_goroutine_stacks"] = extra
 if err != nil { result["constructor_error"] = err.Error() }
 json.NewEncoder(os.Stdout).Encode(result)
 if requests.Load() == 0 || err != nil { os.Exit(1) }
}
